window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["model-evaluation"]={"title":"模型评测与基准：把“更强”变成可复现证据","subtitle":"从估计对象、采样预算和 pass@k，到污染、裁判偏差、置信区间与发布门槛。","thesis":"模型评测不是给模型贴一个总分，而是在固定任务分布、工具、提示、采样预算和评分规则后，估计一个带不确定性的能力剖面。结论成立的前提是<b>题目未泄漏、条件可比、度量与使用方式一致</b>；否则精确到小数点的分数也可能没有决策价值。","quality":{"contractVersion":2,"examples":[{"section":4,"evidence":{"setup":"100 道退款题","rule":"点估计的差不等于稳定差异","steps":"A 的 82% 与 B 的 78% 区间大量重叠","interpretation":"一百题不足以强断言"}}],"formulas":[{"id":"model-eval-binomial-se","section":4,"formulaIndex":1,"symbols":[{"name":"SE","meaning":"样本准确率估计的标准误","evidence":"输出标准误 SE"},{"name":"phat","meaning":"样本中回答正确的比例","evidence":"答对比例 phat"},{"name":"n","meaning":"独立评测样本数量","evidence":"样本量 n"},{"name":"CI95","meaning":"粗略百分之九十五置信区间","evidence":"95% 区间"}]},{"id":"model-eval-pass-k","section":5,"formulaIndex":1,"symbols":[{"name":"passK","meaning":"k 次独立采样至少一次成功的概率","evidence":"输出至少一次成功的理想概率 passK"},{"name":"p","meaning":"单次独立采样成功概率","evidence":"单次独立成功概率 p"},{"name":"k","meaning":"同一任务的采样次数","evidence":"采样次数 k"}]}],"termReviews":[],"sectionContracts":[{"section":1,"definition":{"answer":"模型评测估计模型在特定分布配置和指标下的能力。","evidence":"先说清楚究竟在估计什么"},"problem":{"answer":"它反驳模型存在脱离使用场景的单一真实能力分。","evidence":"有没有一个脱离场景的“真实能力分”"},"inputOutput":{"answer":"输入 M、D、C、Y，输出带不确定性的能力估计。","evidence":"输出带不确定性的能力估计"},"mechanism":{"answer":"固定题目提示工具预算和评分后运行有限样本测量。","evidence":"M 在 D、C 下对 Y 的估计"},"interpretation":{"answer":"分数只对给定实验条件成立，不是模型固有常数。","evidence":"不是脱离场景的真实能力常数"},"boundary":{"answer":"分布或配置变化后旧分数不能直接外推。","evidence":"旧分数不能直接外推"}},{"section":2,"definition":{"answer":"模型、组件、应用和线上评测对应不同实验边界。","evidence":"模型评测与应用评测不能互相替代"},"problem":{"answer":"它解释裸模型更好为何进入产品后仍可能更差。","evidence":"为什么装进产品后仍可能更差"},"inputOutput":{"answer":"输入比较对象和控制条件，输出对应评测层级。","evidence":"输出模型、组件、应用或线上实验评测"},"mechanism":{"answer":"模型评测隔离能力，应用评测保留业务全链路。","evidence":"前者便于归因，后者支持发布"},"interpretation":{"answer":"裸模型分数不包含真实权限延迟和用户结果。","evidence":"不能替代端到端权限、延迟和用户结果验收"},"boundary":{"answer":"两类评测必须组合使用，不能互相替代。","evidence":"不能互相替代"}},{"section":3,"definition":{"answer":"公平模型比较固定题目提示工具预算采样和评分条件。","evidence":"一次公平比较需要固定哪些变量"},"problem":{"answer":"它解释两个准确率八十为何可能完全不可比。","evidence":"为什么可能完全不可比"},"inputOutput":{"answer":"输入相同实验条件，输出逐题结果和质量成本曲线。","evidence":"输出可比较的逐题结果及质量成本曲线"},"mechanism":{"answer":"预注册条件并保存配置哈希版本和随机种子。","evidence":"预算不同就是不同处理条件"},"interpretation":{"answer":"单次生成与百次挑最好回答的是不同使用问题。","evidence":"不能把单次生成与百次挑最好称为公平比较"},"boundary":{"answer":"失败超时必须按预先规则计分且不得静默丢弃。","evidence":"失败和超时必须按预注册规则计分"}},{"section":4,"definition":{"answer":"置信区间描述有限样本准确率估计的统计不确定性。","evidence":"运行示例：100 道退款题上的差距有多确定"},"problem":{"answer":"它判断八十二题对与七十八题对能否证明模型更强。","evidence":"能直接宣布 A 更强吗"},"inputOutput":{"answer":"输入 n、phat 和配对结果，输出标准误区间和差异证据。","evidence":"输出标准误 SE、95% 区间和配对差异证据"},"mechanism":{"answer":"按二项比例计算标准误，并保留同题配对差异。","evidence":"SE=sqrt(phat×(1−phat)/n)"},"interpretation":{"answer":"区间大量重叠说明当前样本不足以支持强结论。","evidence":"说明一百题不足以强断言"},"boundary":{"answer":"关键风险切片可以独立否决总体点估计优势。","evidence":"高风险切片可独立否决总体优势"}},{"section":5,"definition":{"answer":"passK 衡量 k 次独立采样至少出现一次成功的理想概率。","evidence":"pass@k 把模型质量和计算预算混在一起"},"problem":{"answer":"它解释 pass100 高为何单次生成仍频繁失败。","evidence":"为什么用户点一次生成仍可能频繁失败"},"inputOutput":{"answer":"输入 p 和 k，输出至少一次成功的理想概率。","evidence":"输出至少一次成功的理想概率 passK"},"mechanism":{"answer":"用一减去 k 次全部失败概率进行计算。","evidence":"passK=1−(1−p)^k"},"interpretation":{"answer":"数值提高主要来自增加采样计算而非单次能力突变。","evidence":"提高主要来自十倍计算预算"},"boundary":{"answer":"真实错误相关且需验证器，因此公式只是上界直觉。","evidence":"公式只是上界直觉"}},{"section":6,"definition":{"answer":"基准污染包括题目答案及其镜像翻译讲解衍生文本泄漏。","evidence":"公开基准为什么会被污染和过拟合"},"problem":{"answer":"它回答从未显式微调是否足以证明模型没见过题。","evidence":"就能算“未见过”吗"},"inputOutput":{"answer":"输入题目衍生与近邻，输出污染风险和治理决定。","evidence":"输出污染风险、保留、替换或降权决定"},"mechanism":{"answer":"结合时间新题私有门禁语义筛查和查看次数治理。","evidence":"共同降低风险"},"interpretation":{"answer":"词面去重无法识别改写和组织层榜单过拟合。","evidence":"词面去重也抓不到改写"},"boundary":{"answer":"私有题降低泄漏但不保证代表生产分布。","evidence":"不保证代表真实用户分布"}},{"section":7,"definition":{"answer":"模型评分组合确定规则、执行测试、LLM 裁判和领域人工。","evidence":"自动指标、LLM 裁判与人工盲评"},"problem":{"answer":"它解释评分器自身为什么也必须接受评测。","evidence":"为什么评分器本身也要接受评测"},"inputOutput":{"answer":"输入多类仪器，输出属性分数分歧和仲裁结果。","evidence":"输出各属性分数、分歧及仲裁结果"},"mechanism":{"answer":"用盲化换序双标和人工金标测量各自偏差。","evidence":"用盲化、换序、双标和金标校准"},"interpretation":{"answer":"组合仪器的目的在暴露盲区而不是投票造真值。","evidence":"不是投票制造真值"},"boundary":{"answer":"规则覆盖、裁判偏差和人工疲劳都必须显式报告。","evidence":"组合仪器的目的不是投票制造真值，而是让各自的盲区可见"}},{"section":8,"definition":{"answer":"模型发布门槛把离线结果转成替换路由保留或回滚决定。","evidence":"从排行榜到发布门槛"},"problem":{"answer":"它回答模型总分提高后是否应该真正换模型。","evidence":"怎样把证据转成“换不换模型”的决定"},"inputOutput":{"answer":"输入切片区间成本延迟和线上结果，输出发布方案。","evidence":"输出替换、路由、保留或回滚方案"},"mechanism":{"answer":"先过硬门槛，再比较帕累托并进行影子金丝雀。","evidence":"先判越权隐私等硬门槛"},"interpretation":{"answer":"离线胜出只有迁移到真实流量后才是生产证据。","evidence":"经过影子或小流量才能成为生产证据"},"boundary":{"answer":"不得通过删门禁题或换指标放行失败候选。","evidence":"不能通过删题或改指标来放行"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分模型评测与应用评测；手算准确率置信区间和 pass@k；识别污染与裁判偏差；设计可复现的评测卡。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>先说清楚究竟在估计什么<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">同一个模型到底有没有一个脱离场景的“真实能力分”？</p><p>没有。评测结果是模型在某个题目分布、提示模板、工具权限、推理预算和评分器下的表现估计。退款助手场景里，我们可能测政策问答、证据引用、金额计算、拒绝越权和多轮澄清；这些能力不能由一个通用知识榜单替代。</p><p>因此报告应写成“模型 M 在测试集 D、配置 C 下，对指标 Y 的估计”，而不是“模型 M 有 82 分”。模型名字只是实验对象的一部分，系统提示、温度、最大 token、reasoning effort、候选数和工具都属于处理条件。</p><div class=\"dd-note\"><b>认知锚点：</b>评测不是给能力拍照，而是用有限样本测量未来使用表现；样本和仪器都可能偏。</div><p>模型评测输入模型快照 M、测试分布 D、推理配置 C 和目标指标 Y，输出带不确定性的能力估计。分数只对给定题目、提示、工具和预算成立，不是脱离场景的真实能力常数；结果应写成 M 在 D、C 下对 Y 的估计。分布或配置改变后旧分数不能直接外推。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>模型评测与应用评测不能互相替代<span class=\"dd-badge intuition\">消歧</span></h2><p class=\"dd-lead\">裸模型答得更好，为什么装进产品后仍可能更差？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>固定什么</th><th>回答什么问题</th><th>退款助手例子</th></tr></thead><tbody><tr><td>模型评测</td><td>提示、工具和题集</td><td>候选模型在同条件下谁更会做</td><td>给同一政策片段，谁判断得更准</td></tr><tr><td>组件评测</td><td>模型，替换一个组件</td><td>检索或重排是否改善</td><td>正确条款能否进入 top-5</td></tr><tr><td>应用评测</td><td>完整版本与业务流程</td><td>端到端是否达成目标</td><td>引用、权限、延迟和用户结果是否合格</td></tr><tr><td>线上实验</td><td>分流规则和护栏</td><td>离线收益能否迁移</td><td>转人工率与错误承诺是否下降</td></tr></tbody></table></div><p>模型评测隔离能力，便于归因；应用评测保留真实链路，便于决策。两者应像单元测试和端到端测试一样组合，而不是二选一。</p><p>层级辨析输入待比较对象和固定条件，输出模型、组件、应用或线上实验评测。模型评测固定系统条件隔离候选能力，应用评测保留完整链判断业务结果；前者便于归因，后者支持发布。裸模型高分不能替代端到端权限、延迟和用户结果验收。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>一次公平比较需要固定哪些变量<span class=\"dd-badge eng\">实验设计</span></h2><p class=\"dd-lead\">两个报告都写“准确率 80%”，为什么可能完全不可比？</p><p>至少固定题目与版本、few-shot 样例、系统提示、输出解析、上下文、工具、token 上限、停止条件、温度、候选数、重试和评分器。若比较成本收益，预算本身就是自变量，应画出质量—成本曲线，而非只选各自最有利的点。</p><ol class=\"dd-steps\"><li>预注册主指标、关键切片和失败门槛，避免看完结果再挑指标。</li><li>保存可执行配置、模型快照、数据哈希与随机种子；托管模型至少记录日期和版本。</li><li>交错或随机化运行顺序，减少服务更新、限流和时间漂移的影响。</li><li>失败重试必须按预先规则计分；静默丢弃超时会虚增质量。</li></ol><div class=\"dd-note warn\"><b>常见偷换：</b>模型 A 用单次输出，模型 B 每题生成 100 个候选再挑最好。即使最后分数相同，也不代表交互式单次使用同样可靠。</div><p>公平实验输入相同题目版本、fewShot、提示、工具、token、温度、候选、重试和评分器，输出可比较的逐题结果及质量成本曲线。预算不同就是不同处理条件，不能把单次生成与百次挑最好称为公平比较；失败和超时必须按预注册规则计分。托管模型还需记录日期版本。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>运行示例：100 道退款题上的差距有多确定<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">模型 A 答对 82 题、模型 B 答对 78 题，能直接宣布 A 更强吗？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 700 230\" role=\"img\" aria-label=\"退款题评测从固定任务到切片和置信区间的流程\"><defs><marker id=\"me1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"18\" y=\"75\" width=\"128\" height=\"72\" rx=\"9\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"82\" y=\"101\" text-anchor=\"middle\" class=\"svg-t\">100 道冻结题</text><text x=\"82\" y=\"122\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">资格/金额/权限切片</text><path d=\"M146,111 L205,111\" stroke=\"#6b7484\" marker-end=\"url(#me1)\"/><rect x=\"207\" y=\"32\" width=\"142\" height=\"64\" rx=\"9\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"278\" y=\"57\" text-anchor=\"middle\" class=\"svg-t\">模型 A：82/100</text><text x=\"278\" y=\"78\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">95% CI 约 73%–88%</text><rect x=\"207\" y=\"132\" width=\"142\" height=\"64\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"278\" y=\"157\" text-anchor=\"middle\" class=\"svg-t\">模型 B：78/100</text><text x=\"278\" y=\"178\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">95% CI 约 69%–85%</text><path d=\"M349,64 L420,91\" stroke=\"#6b7484\" marker-end=\"url(#me1)\"/><path d=\"M349,164 L420,137\" stroke=\"#6b7484\" marker-end=\"url(#me1)\"/><rect x=\"422\" y=\"76\" width=\"128\" height=\"76\" rx=\"9\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"486\" y=\"101\" text-anchor=\"middle\" class=\"svg-t\">区间大量重叠</text><text x=\"486\" y=\"122\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">4 点差距证据较弱</text><text x=\"486\" y=\"140\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">还要看配对差异</text><path d=\"M550,114 L608,114\" stroke=\"#6b7484\" marker-end=\"url(#me1)\"/><rect x=\"610\" y=\"82\" width=\"72\" height=\"64\" rx=\"9\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"646\" y=\"107\" text-anchor=\"middle\" class=\"svg-t\">增加样本</text><text x=\"646\" y=\"128\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">检查切片</text></svg><figcaption>图 1　点估计的差不等于稳定差异；同一批题的配对结果比两个独立准确率更有信息。</figcaption></figure><div class=\"dd-formula\"><math display=\"block\" aria-label=\"二项比例标准误与粗略置信区间\"><mi>SE</mi><mo>(</mo><mi>phat</mi><mo>)</mo><mo>≈</mo><msqrt><mfrac><mrow><mi>phat</mi><mo>×</mo><mo>(</mo><mn>1</mn><mo>−</mo><mi>phat</mi><mo>)</mo></mrow><mi>n</mi></mfrac></msqrt><mo>;</mo><mi>CI95</mi><mo>≈</mo><mi>phat</mi><mo>±</mo><mn>1.96</mn><mo>×</mo><mi>SE</mi></math></div><p>A 的标准误约 <span class=\"dd-radical\" role=\"math\" aria-label=\"0.82×0.18/100 的平方根\"><span class=\"dd-radicand\">0.82×0.18/100</span></span>=0.038，粗略区间约 74.5%–89.5%；Wilson 区间约 73%–88%。B 的 Wilson 区间约 69%–85%。区间重叠不等于“绝无差异”，但说明仅凭 100 题和 4 点差距难下强结论。</p><p>若两模型答的是同一批题，应保留每题配对：A 独对 12 题、B 独对 8 题，其余同对或同错。真正区分模型的信息主要来自这 20 个不一致样本，可用 McNemar 检验或 bootstrap 差值区间。再看高风险“越权退款”切片：A 2/10，B 8/10；总分更高的 A 反而不能上线。</p><p>准确率案例输入样本量 n、答对比例 phat 及同题配对结果，输出标准误 SE、95% 区间和配对差异证据。SE=sqrt(phat×(1−phat)/n)，粗略区间为 phat±1.96×SE；A 的 82% 与 B 的 78% 区间大量重叠，说明一百题不足以强断言。高风险切片可独立否决总体优势。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>pass@k 把模型质量和计算预算混在一起<span class=\"dd-badge math\">采样</span></h2><p class=\"dd-lead\">代码模型报告 pass@100=90%，为什么用户点一次生成仍可能频繁失败？</p><p>若单次独立成功概率为 p，理想化的“k 次至少一次成功”是 <code>1−(1−p)^k</code>。当 p=0.1 时，pass@1=10%，pass@10≈65.1%；数字跃升主要来自十倍采样，而非单次模型突然更聪明。真实候选错误相关，且系统还需要可靠验证器从候选中选对，所以这个公式通常只是上界直觉。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>报告</th><th>用户得到什么</th><th>必须同时披露</th></tr></thead><tbody><tr><td>pass@1</td><td>一次采样命中</td><td>温度、token 与提示</td></tr><tr><td>pass@k</td><td>候选池至少一个命中</td><td>k、总 token、候选相关性</td></tr><tr><td>选后成功率</td><td>验证器实际交付正确候选</td><td>验证开销和误选率</td></tr><tr><td>端到端成功率</td><td>真实流程完成</td><td>工具、超时、失败重试</td></tr></tbody></table></div><p>比较推理模型也同理：固定 token 可能不公平，固定价格或延迟也各回答不同问题。最诚实的做法是报告帕累托前沿，让读者按自己的预算选点。</p><p>passK 输入单次独立成功概率 p 和采样次数 k，输出至少一次成功的理想概率 passK=1−(1−p)^k。p=0.1、k=10 得约 65.1%，提高主要来自十倍计算预算；真实错误相关且还需验证器选对，因此公式只是上界直觉。报告 passK 必须同时披露 k、总 token、延迟和选择器。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"独立采样至少一次成功的概率\"><mi>passK</mi><mo>=</mo><mn>1</mn><mo>−</mo><msup><mrow><mo>(</mo><mn>1</mn><mo>−</mo><mi>p</mi><mo>)</mo></mrow><mi>k</mi></msup></math></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>公开基准为什么会被污染和过拟合<span class=\"dd-badge eng\">失效</span></h2><p class=\"dd-lead\">一套题从未显式用于微调，就能算“未见过”吗？</p><p>不能。题目、答案、网页镜像、讲解、翻译和模型生成的衍生文本都可能进入预训练；团队还会反复依据公开榜单改数据和配方，形成组织层面的测试集过拟合。词面去重抓不到改写污染，异常高分也不能单独证明记忆。</p><p>防线包括：按时间构建新题；保留私有测试；用语义近邻和可疑解题痕迹筛查；把调参开发集与最终门禁分离；记录每次查看测试结果的次数。对会快速饱和的题集，应周期性替换，而不是永久沿用。</p><div class=\"dd-note warn\"><b>边界：</b>私有不自动等于代表性。若退款题全由内部专家写成规范句，仍可能漏掉真实用户的口语、错别字和信息缺失。</div><p>污染治理输入题目答案镜像翻译讲解和语义近邻，输出污染风险、保留、替换或降权决定。未显式微调不表示预训练没见过，词面去重也抓不到改写；时间新题、私有门禁和语义筛查共同降低风险。私有只降低泄漏，不保证代表真实用户分布。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>自动指标、LLM 裁判与人工盲评<span class=\"dd-badge intuition\">测量偏差</span></h2><p class=\"dd-lead\">评分器输出一个数，为什么评分器本身也要接受评测？</p><p>精确匹配便宜可复现，却会错罚等价表述；程序测试对代码和结构强，但只覆盖写出的断言；LLM 裁判能理解语义，却有位置、长度、风格、自家模型和提示注入偏差；人工最接近真实判断，但会疲劳且标准不一致。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>仪器</th><th>适合</th><th>主要偏差</th><th>校验方法</th></tr></thead><tbody><tr><td>确定规则/测试</td><td>数值、schema、可执行结果</td><td>覆盖不足</td><td>变异测试与反例</td></tr><tr><td>LLM 裁判</td><td>帮助性、完整性、文风</td><td>顺序/长度/同源偏好</td><td>对调位置、盲化、人工金标</td></tr><tr><td>领域人工</td><td>高风险与新型失败</td><td>分歧和疲劳</td><td>双标、仲裁、一致性</td></tr></tbody></table></div><p>退款答案可先用程序检查金额、权限和引用 ID，再让盲化裁判评解释清晰度，最后对高风险和分歧样本由专家仲裁。组合仪器的目的不是投票制造真值，而是让各自的盲区可见。</p><p>评分组合输入确定规则、可执行测试、LLM 裁判和领域人工，输出各属性分数、分歧及仲裁结果。规则可复现但覆盖有限，裁判懂语义但有顺序长度同源偏差，人工有资格却会疲劳；用盲化、换序、双标和金标校准。多个仪器不是投票制造真值，而是暴露盲区。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>从排行榜到发布门槛<span class=\"dd-badge eng\">决策</span></h2><p class=\"dd-lead\">模型总分提高后，怎样把证据转成“换不换模型”的决定？</p><p>先定义不可退化的硬门槛，如越权动作率、隐私泄漏和关键语言切片；再比较任务质量、成本、p95 延迟与吞吐。用 paired bootstrap 给差值区间，列出失败迁移：哪些旧错误修复、哪些新错误出现。只有在代表性流量上经过影子或小流量验证，离线胜出才成为发布证据。</p><ol class=\"dd-steps\"><li>评测卡冻结数据版本、配置和主指标。</li><li>结果页同时报告总体、切片、区间、成本和错误样例。</li><li>发布策略写清回滚阈值，而非只留一张排行榜。</li><li>生产新失败回流候选集；经审核后进入下一版，不污染当前门禁。</li></ol><p>“最佳模型”常常不存在：一个模型在低延迟、高风险安全和长上下文三个维度可能各有胜负，模型路由比全量替换更合适。</p><p>发布决策输入总体与切片差值区间、成本、延迟、错误迁移和线上验证，输出替换、路由、保留或回滚方案。先判越权隐私等硬门槛，再比较质量成本帕累托；离线胜出只有经过影子或小流量才能成为生产证据。门禁集失败不能通过删题或改指标来放行。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与概念依赖<span class=\"dd-badge intuition\">误区与学习路线</span></h2><p class=\"dd-lead\">看到漂亮分数时，先问实验对象、测量仪器和不确定性。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>常见误解</th><th>更准确的理解</th></tr></thead><tbody><tr><td>题目固定才可复现</td><td>数据、提示、预算、工具、解析和评分都要固定</td></tr><tr><td>总体平均最高就是最好</td><td>关键切片硬门槛可否决总体提升</td></tr><tr><td>公开榜单最客观</td><td>可能污染、饱和且与目标分布不匹配</td></tr><tr><td>LLM 裁判比人一致，所以是真值</td><td>一致的系统偏差仍是偏差，需金标校准</td></tr><tr><td>置信区间重叠就毫无差异</td><td>应分析配对差值及决策所需最小效应</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>概率统计、过拟合、损失函数</td></tr><tr><td><b>本页核心</b></td><td>实验条件、采样预算、切片、污染、评判器、置信区间</td></tr><tr><td>向产品</td><td>LLM 应用评测、模型选型、模型路由</td></tr><tr><td>向生产</td><td>不确定性校准、可观测性、数据漂移、红队测试</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>定义目标任务分布</li><li>冻结数据与推理条件</li><li>选择互补评分器</li><li>运行并保留逐题结果</li><li>估计差值与不确定性</li><li>检查切片/污染/成本后决策</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>为什么“模型 A 82 分”不是完整结论？</li><li>p=0.1 时理想 pass@10 约多少？</li><li>同题比较为何应保留配对结果？</li><li>私有题为什么仍可能无效？</li><li>模型裁判怎样降低位置偏差？</li><li>假设“模型评测与基准：把“更强”变成可复现证据”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>缺少任务分布、配置、预算、评分器和统计不确定性。</li><li>1−0.9^10≈65.1%，但相关错误和选择器会降低可交付成功率。</li><li>差异信息来自两模型结果不一致的题，可减少题目难度噪声。</li><li>它可能不代表生产分布，私有只缓解泄漏，不保证代表性。</li><li>候选盲化并交换顺序，结合人工金标测偏差。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2211.09110\" target=\"_blank\" rel=\"noopener\">HELM: Holistic Evaluation of Language Models</a>：多场景、透明和可复现评测</li><li><a href=\"https://arxiv.org/abs/2107.03374\" target=\"_blank\" rel=\"noopener\">Evaluating Large Language Models Trained on Code</a>：pass@k 估计与代码评测</li><li><a href=\"https://arxiv.org/abs/2306.05685\" target=\"_blank\" rel=\"noopener\">Judging LLM-as-a-Judge with MT-Bench and Chatbot Arena</a>：模型裁判与偏差</li><li><a href=\"https://arxiv.org/abs/2310.06770\" target=\"_blank\" rel=\"noopener\">SWE-bench</a>：真实仓库任务及执行式评测</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
